record.field:
# Find all partners with SERP configuration
partners = env['res.partner'].search([
    ('serp_domain', '!=', False),
    ('serp_keywords', '!=', False),
    ('serp_provider_id', '!=', False)
])

# Execute SERP check for each partner
for partner in partners:
    try:
        partner.action_check_serp()
    except Exception as e:
        _logger.error(f"SERP check failed for partner {partner.name}: {str(e)}")
